{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Validate required fields
    if not nodes:
        raise ValueError("nodes is empty")
    if not core_distance:
        raise ValueError("core_distance is empty")
    if distances is None:
        raise ValueError("distances is missing")
    for n in nodes:
        if n not in core_distance:
            raise ValueError(f"Missing core_distance for node {n}")

    # Compute mutual reachability edges
    # mutual_reachability(u, v) = max(core_dist[u], core_dist[v], dist(u, v))
    mr_edges = []
    for edge in distances:
        u, v, d = edge[0], edge[1], edge[2]
        # Canonicalize: sort endpoints lexicographically
        if u > v:
            u, v = v, u
        mr = max(core_distance[u], core_distance[v], d)
        mr_edges.append((u, v, mr))

    # Sort by mutual reachability weight, then by first endpoint, then by second endpoint
    mr_edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Kruskal's MST with union-find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0

    for u, v, w in mr_edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break

    # Reject disconnected inputs
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("Graph is disconnected; cannot form a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
